function ledgerLinked(mode='EXACT'){
 const raw={rules:[],reason:'원장 정책 참조 원형',reviewRefs:[]},policyRef={id:id(20),version:1,contentHash:hash(raw)},{f,saved}=approvalLinked('EXACT',policyRef),old=f.state.beforeAuth;
 if(mode!=='ABSENT'){f.tables.permission_policies=[{id:policyRef.id,project_id:pid,head_version:1,created_by:pastActor,created_at:at}];f.tables.permission_policy_versions=[{project_id:pid,policy_id:policyRef.id,version:1,rules_json:raw.rules,content_hash:policyRef.contentHash,reason:raw.reason,review_refs:raw.reviewRefs,created_by:pastActor,created_at:at,client_id:null,command_id:null}];}
 f.state.beforeAuth=n=>{old?.(n);if(n===44){
  for(const c of f.t('commands')){c.draft_id=null;c.received_at??=c.completed_at;}
  if(mode==='CONFLICT'){const changed={...policyRef,contentHash:hash({...raw,reason:'독립 관측 정책 내용'})};for(const c of f.t('commands')){c.policy_ref=clone(changed);const target=c.result_ref.data.ref??c.result_ref.data.artifactRef,digest=hash({projectId:pid,actorId:c.actor_id,clientId:c.client_id,controlGeneration:c.control_generation,requestHash:c.request_hash,policyRef:changed,targetRef:target}),a=f.t('authorization_receipts').find(a=>a.command_id===c.id),e=f.t('audit_events').find(e=>e.command_id===c.id);a.policy_ref=e.policy_ref=clone(changed);a.scope_digest=e.scope_digest=digest;}}
  if(mode==='TABLE')f.state.failTable='commands';if(mode==='ROLLBACK'){f.state.failRollback=true;f.state.afterQuery=q=>{if(q.includes('FROM anvil.commands '))f.abort.abort();};}
 }};return{f,saved,policyRef};
}
