test('projectComposition ownDraft actual24 profile preserves original hash and no observation',async()=>{const f=fixture(),own=withOwnDraft(f),r=await f.run(),c=r.components.find((c:any)=>c.name==='ProjectCreationDraft');assert(c,'actual own draft profile missing');assert.equal(c.rowCounts.drafts,1);assert.equal(c.rowCounts.artifacts,1);assert.equal(c.observation,null);assert.equal(c.declarations.observationExport,'NOT_EXPORTED');assert.equal(c.declarations.originalDraftContentHash,'NOT_STORED');assert.equal(c.scope,'OWN_CONSUMED_PROJECT_DRAFT_SELECTED_ADOPTIONS_ONLY');assert.equal(r.usage.fileCount,1);assert.equal(r.usage.inputBytes,own.uploads[0].ref.bytes);assert.deepEqual(r.references.find((v:any)=>v.namespace==='ARTIFACT').sources,['ProjectCreationDraft']);assert.equal(r.components.length,24);assert(r.notCollected.includes('PROJECT_DRAFT_ATTACHMENTS_CONTROL_HANDOFF_BASELINE_DRAFTS'));assert(!r.references.some((v:any)=>/DRAFT/.test(v.namespace)));for(const marker of ['private-project-name','private-purpose','draft-blobs/',actorId,clientId])assert(!JSON.stringify(r).includes(marker));});

test('projectComposition ownDraft empty and owner-project-consumption filters do not leak counts',async()=>{for(const mode of ['EMPTY','OTHER','PROJECT','UNCONSUMED']){const f=fixture();if(mode!=='EMPTY'){const own=withOwnDraft(f);if(mode==='OTHER')own.draft.owner_user_id=id(99);if(mode==='PROJECT')own.draft.consumed_project_id=id(98);if(mode==='UNCONSUMED')own.draft.consumed_project_id=null;}const r=await f.run(),c=r.components.find((c:any)=>c.name==='ProjectCreationDraft');assert.equal(c.rowCounts.drafts,0);assert.equal(c.rowCounts.artifacts,0);assert.equal(c.observation,null);assert.equal(r.usage.fileCount,0);assert(f.trace.filter(q=>q.sql.includes('FROM anvil.project_drafts t')).every(q=>q.sql.includes('t.owner_user_id=')&&q.sql.includes('t.consumed_project_id=')));}});
test('projectComposition ownDraft real source nine-field hash remains exact',async()=>{const f=fixture();withOwnDraft(f);const r=await f.run(),source=await import('../../../apps/server/modules/backups/project-creation-draft-inventory.ts'),actual=await source.collectProjectCreationDraftInventory(f.access,token,f.input,f.abort.signal),c=r.components.find((c:any)=>c.name==='ProjectCreationDraft');assert.equal(c.originalHash,actual.inventoryHash);assert.equal(c.resultDigest,hash(actual));assert.deepEqual(c.issues,actual.issues);assert.equal(c.declarations.creationWriteProof,'NOT_PERFORMED');});
test('projectComposition ownDraft exact shared artifact union merges all sources once',async()=>{const f=fixture(true),a=f.artifact;withOwnDraft(f,1,{artifactId:a.id,bytes:a.bytes,contentHash:a.content_hash,mediaType:a.media_type});f.input.limits.fileCount=1;f.input.limits.inputBytes=a.bytes;const r=await f.run(),entry=r.references.find((v:any)=>v.namespace==='ARTIFACT');assert.deepEqual(entry.sources,['Document','Conversation','ProjectCreationDraft']);assert.equal(r.usage.fileCount,1);assert.equal(r.usage.inputBytes,a.bytes);});
test('projectComposition ownDraft independent later tuple conflict and global distinct union limits',async()=>{for(const mode of ['CONFLICT','FILES','BYTES']){const f=fixture(true),a=clone(f.artifact);if(mode==='CONFLICT'){const own=withOwnDraft(f,1,{artifactId:a.id,bytes:a.bytes,contentHash:'e'.repeat(64),mediaType:a.media_type}),later=clone(own.uploads[0].f);Object.assign(own.uploads[0].f,a);f.state.beforeAuth=n=>{if(n===48)Object.assign(own.uploads[0].f,later);};}else{withOwnDraft(f);if(mode==='FILES')f.input.limits.fileCount=1;else f.input.limits.inputBytes=Math.max(a.bytes,1);}await assert.rejects(f.run(),rejected(mode==='CONFLICT'?503:413,mode==='CONFLICT'?'PROJECT_INVENTORY_REFERENCE_CONFLICT':undefined));assert.equal(f.state.connects,24);assert.equal(f.state.releases,24);}});
test('projectComposition ownDraft derived inspection issue is separate from exact source hash',async()=>{for(const status of ['UNKNOWN','SUSPECTED']){const f=fixture(),own=withOwnDraft(f),x=own.uploads[0];x.f.inspection_json=status==='UNKNOWN'?null:{...x.f.inspection_json,state:'SUSPECTED'};x.u.result_json.data.inspection=x.f.inspection_json;const r=await f.run(),c=r.components.find((c:any)=>c.name==='ProjectCreationDraft'),derived=r.issues.find((v:any)=>v.source==='ProjectCreationDraft'&&v.origin==='COMPOSITION_DERIVED');assert.equal(c.issues.length,0);assert.equal(derived.issue.code,'ARTIFACT_INSPECTION_UNKNOWN');assert.deepEqual(derived.issue.ref,x.ref);assert.equal(derived.issue.sourceInspectionStatus,status);}});

test('projectComposition ownDraft final current guard and outer guard still close whole result',async()=>{for(const mode of ['CONSUMPTION','OWNER','CANCEL','EXPIRY']){const f=fixture(),own=withOwnDraft(f),oldNow=performance.now;let elapsed=0;if(mode==='EXPIRY')Object.defineProperty(performance,'now',{configurable:true,value:()=>elapsed});f.state.beforeAuth=n=>{if(n===49){if(mode==='CONSUMPTION')own.draft.consumed_project_id=id(99);if(mode==='EXPIRY')f.state.sessionMs=500;}if(n===50&&mode==='OWNER')f.state.owner='MEMBER';};if(mode==='CANCEL')f.state.cancelPhase=50;if(mode==='EXPIRY')f.state.afterCommit=n=>{if(n===49)elapsed=600;};try{await assert.rejects(f.run(),rejected(mode==='CANCEL'?409:mode==='EXPIRY'?503:404));assert.equal(f.state.releases,f.state.connects);if(mode==='EXPIRY'){assert.equal(elapsed,600);assert.equal(f.state.sessionMs,500);assert.equal(f.state.auth,49);}}finally{if(mode==='EXPIRY')Object.defineProperty(performance,'now',{configurable:true,value:oldNow});}}});
